// fungsi desimal ke heksadesimal
function decimalArrayToHexArray(decimalArray) {
    return decimalArray.map(decimal => decimal.toString(16))
}

// fungsi heksadesimal ke ascii
function hexToAscii(hexArray) {
    return hexArray.map(hex => {
        let asciiString = ''
        for (let i = 0; i < hex.length; i += 2) {
            asciiString += String.fromCharCode(parseInt(hex.substr(i, 2), 16))
        }
        return asciiString
    })
}

// mengeluarkan dari array
function combineAsciiStrings(asciiArray) {
    return asciiArray.join('')
}

